cpp.setup:
auto* control = new fluent::navigation::Stepper(%PARENT%);
fluent::navigation::StepperItem accountStep(QStringLiteral("Account"), QStringLiteral("Basic info"));
accountStep.state = fluent::navigation::Stepper::Completed;
control->addItem(accountStep);
control->addItem(fluent::navigation::StepperItem(QStringLiteral("Plan"), QStringLiteral("Choose tier")));
control->addItem(fluent::navigation::StepperItem(QStringLiteral("Confirm"), QStringLiteral("Finish")));
control->setCurrentIndex(1);
QObject::connect(control, &fluent::navigation::Stepper::stepRequested, control, &fluent::navigation::Stepper::setCurrentIndex);
